    link_count = [0]

    def resolve_impl(current_path, remaining_components):
        # Check link limit
        if link_count[0] > 8:
            return None

        # No more components to resolve
        if not remaining_components:
            return current_path if current_path else '/'

        # Get next component
        component = remaining_components[0]
        rest = remaining_components[1:]

        # Skip empty and '.' components
        if component == '' or component == '.':
            return resolve_impl(current_path, rest)

        # Handle '..'
        if component == '..':
            if current_path == '' or current_path == '/':
                # Already at root
                return resolve_impl('/', rest)
            else:
                # Go to parent
                parent = current_path.rsplit('/', 1)[0]
                if parent == '':
                    parent = '/'
                return resolve_impl(parent, rest)

        # Normal component: append to current path
        if current_path == '/':
            new_path = '/' + component
        elif current_path == '':
            new_path = component
        else:
            new_path = current_path + '/' + component

        # Check if this path is a symlink
        if new_path in links:
            link_count[0] += 1
            if link_count[0] > 8:
                return None

            target = links[new_path]

            # Parse target into components
            if target.startswith('/'):
                # Absolute link
                target_components = [c for c in target.split('/') if c != '']
                return resolve_impl('/', target_components + rest)
            else:
                # Relative link - relative to the directory containing the symlink
                if new_path == '/':
                    link_dir = '/'
                else:
                    link_dir = new_path.rsplit('/', 1)[0]
                    if link_dir == '':
                        link_dir = '/'

                target_components = [c for c in target.split('/') if c != '']
                return resolve_impl(link_dir, target_components + rest)

        # Not a symlink, continue with rest of components
        return resolve_impl(new_path, rest)

    # Handle initial path
    if path.startswith('/'):
        # Absolute path
        components = [c for c in path.split('/') if c != '']
        result = resolve_impl('/', components)
    else:
        # Relative path - relative to cwd
        components = [c for c in path.split('/') if c != '']
        result = resolve_impl(cwd, components)

    # Normalize result
    if result is None:
        return None

    if result == '':
        return '/'

    return result

